def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row),key=lambda x:sum(row.count(x) for row in grid))
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); stack.append((yy,xx))
        r0=min(y for y,x in comp); r1=max(y for y,x in comp); c0=min(x for y,x in comp); c1=max(x for y,x in comp)
        border={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in (r0,r1) or x in (c0,c1)}
        if set(comp)==border and r1-r0>=2 and c1-c0>=2 and all(grid[y][x]==bg for y in range(r0+1,r1) for x in range(c0+1,c1)):
          fill=7 if ((r1-r0-1)*(c1-c0-1))%2 else 2
          for y in range(r0+1,r1):
            for x in range(c0+1,c1): out[y][x]=fill
    return out

